const input = $json.body ?? $json;
const email = String(input.email ?? '').trim().toLowerCase();
const source = String(input.source ?? 'web').trim().toLowerCase();
const externalId = String(input.lead_id ?? input.id ?? '').trim();

if (!email) {
  return [{ json: { ok: false, status: 'invalid', error: 'email is required' } }];
}

const operationKey = `lead:${source}:${externalId || email}`;
const state = $getWorkflowStaticData('global');
state.seen ??= {};

if (state.seen[operationKey]) {
  return [{
    json: {
      ok: true,
      status: 'duplicate',
      duplicate: true,
      operationKey,
      firstSeenAt: state.seen[operationKey],
      note: 'Safe duplicate. Do not create a second CRM record or follow-up.'
    }
  }];
}

const now = new Date().toISOString();
state.seen[operationKey] = now;

return [{
  json: {
    ok: true,
    status: 'accepted',
    duplicate: false,
    operationKey,
    crmUpsert: {
      external_key: operationKey,
      email,
      name: String(input.name ?? '').trim(),
      company: String(input.company ?? '').trim(),
      source
    },
    followUp: {
      lead_key: operationKey,
      due_at: input.follow_up_at ?? null,
      reason: 'new inbound lead'
    },
    receivedAt: now
  }
}];
